20	/// Same plain (non-mocktail) fake shape as
21	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
22	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
23	/// real stream the cubit (built from this fake, not mocked) actually
24	/// subscribes to. `biometricEnabledStream` is a plain broadcast stream, not
25	/// a `Stream.multi` replay wrapper (unlike the production repository) —
26	/// `AccountSettingsCubit`'s own constructor already reads
27	/// [currentBiometricEnabled] directly for its initial state, so no replay
28	/// machinery is needed for a fake with exactly one subscriber.
29	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
30	  bool _value = true;
31	  final _controller = StreamController<bool>.broadcast();
32	
33	  /// The next `setBiometricEnabled()` call's own result — defaults to a
34	  /// failure so a test must opt in to the success path explicitly, same
35	  /// convention as the cubit-level fake.
36	  Either<Failure, Unit> setBiometricEnabledResult = left(
37	    const Failure.malformedResponse(message: 'fake: not configured'),
38	  );
39	
40	  /// Lets a test hold `setBiometricEnabled()` unresolved, to observe
41	  /// `state.isSaving` mid-flight (review finding: the `Switch` must
42	  /// disable itself while a toggle is in flight).
43	  Completer<void>? setBiometricEnabledGate;
44	
45	  @override
46	  bool get currentBiometricEnabled => _value;
47	
48	  @override
49	  Stream<bool> get biometricEnabledStream => _controller.stream;
50	
51	  @override
52	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
53	
54	  @override
55	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
56	    final gate = setBiometricEnabledGate;
57	    if (gate != null) {
58	      await gate.future;
59	    }
60	    final previous = _value;
61	    _emit(enabled);
62	    final result = setBiometricEnabledResult;
63	    if (result.isLeft()) {
64	      _emit(previous);
65	    }
66	    return result;
67	  }
68	
69	  @override
70	  Future<void> dispose() => _controller.close();
71	
72	  void _emit(bool value) {
73	    _value = value;
74	    _controller.add(value);
75	  }
76	}
