315	    expect(find.text('Sem conexão'), findsNothing);
316	    // The toggle's own confirmed value is untouched by the error clear.
317	    final switchWidget = tester.widget<Switch>(find.byType(Switch));
318	    expect(switchWidget.value, isTrue);
319	  });
